def contar_pares(n):
    """Contá los pares del 1 al n."""
    cantidad = 0
    for numero in range(1, n + 1):
        # Un número es par si el resto de dividir por 2 es 0.
        if numero % 2 == 0:
            cantidad = cantidad + 1
    return cantidad


