def cuantos_turnos(hp_rival, dano):
    """Contá turnos hasta debilitar al rival."""
    turnos = 0
    # Mientras el rival tenga HP, atacamos y contamos un turno.
    while hp_rival > 0:
        hp_rival = hp_rival - dano
        turnos = turnos + 1
    return turnos


