def potencia(base, exp):
    """Calculá base ** exp con un bucle."""
    # Cualquier número elevado a 0 es 1, así que arrancamos en 1.
    resultado = 1
    # Repetimos 'exp' veces, multiplicando por la base cada vez.
    for _ in range(exp):
        resultado = resultado * base
    return resultado


